import React, { useState } from 'react';
import { Pressable, StyleSheet, Text, TextInput, View } from 'react-native';
import type { Goal } from '../types';
import { goalColors, palette } from '../theme';
import { addDays, isValidKey, todayKey } from '../lib/dates';
import { ActionButton } from './ui';

type GoalDraft = Omit<Goal, 'id' | 'createdAt'>;

export function GoalForm({ initial, onSubmit, onCancel, submitLabel, testID }: {
  initial?: Goal;
  onSubmit: (draft: GoalDraft) => void;
  onCancel?: () => void;
  submitLabel: string;
  testID?: string;
}) {
  const [name, setName] = useState(initial?.name ?? '');
  const [unit, setUnit] = useState(initial?.unit ?? '');
  const [total, setTotal] = useState(initial ? String(initial.total) : '');
  const [deadline, setDeadline] = useState(initial?.deadline ?? addDays(todayKey(), 30));
  const [color, setColor] = useState(initial?.color ?? goalColors[0]);
  const [obstacle, setObstacle] = useState(initial?.obstacle ?? '');
  const [plan, setPlan] = useState(initial?.plan ?? '');
  const [error, setError] = useState('');

  const totalNum = Number(total);
  const valid = name.trim().length > 0 && unit.trim().length > 0 && Number.isFinite(totalNum) && totalNum > 0 && isValidKey(deadline);

  const submit = () => {
    if (!valid) {
      setError('请填写名称、单位、大于 0 的总量，并使用 YYYY-MM-DD 格式的截止日。');
      return;
    }
    onSubmit({
      name: name.trim(), unit: unit.trim(), total: totalNum, deadline, color,
      obstacle: obstacle.trim(), plan: plan.trim(),
      ...(initial?.isSample ? { isSample: true } : {}),
    });
  };

  return <View style={styles.form} testID={testID}>
    <Field label="目标名称"><TextInput accessibilityLabel="目标名称" onChangeText={setName} placeholder="例如：背完 2000 个英语单词" placeholderTextColor={palette.faint} style={styles.input} testID="goal-name-input" value={name} /></Field>
    <View style={styles.row}>
      <Field flex label="单位"><TextInput accessibilityLabel="单位" onChangeText={setUnit} placeholder="个 / 页 / 节" placeholderTextColor={palette.faint} style={styles.input} testID="goal-unit-input" value={unit} /></Field>
      <Field flex label="总量"><TextInput accessibilityLabel="总量" keyboardType="numeric" onChangeText={setTotal} placeholder="2000" placeholderTextColor={palette.faint} style={styles.input} testID="goal-total-input" value={total} /></Field>
    </View>
    <Field label="截止日（YYYY-MM-DD）"><TextInput accessibilityLabel="截止日" onChangeText={setDeadline} placeholder="2026-09-30" placeholderTextColor={palette.faint} style={styles.input} testID="goal-deadline-input" value={deadline} /></Field>
    <View style={styles.field}>
      <Text style={styles.label}>配色</Text>
      <View style={styles.swatches}>
        {goalColors.map((c) => (
          <Pressable accessibilityLabel={`配色 ${c}`} accessibilityRole="button" key={c} onPress={() => setColor(c)} style={[styles.swatch, { backgroundColor: c }, color === c && styles.swatchActive]} testID={`swatch-${c}`} />
        ))}
      </View>
    </View>
    <Field label="最容易拦住我的障碍（选填）"><TextInput accessibilityLabel="障碍" multiline onChangeText={setObstacle} placeholder="例如：睡前刷手机" placeholderTextColor={palette.faint} style={[styles.input, styles.multiline]} testID="goal-obstacle-input" value={obstacle} /></Field>
    <Field label="如果它出现，我就……（选填）"><TextInput accessibilityLabel="对策" multiline onChangeText={setPlan} placeholder="例如：就先读 5 页书再决定要不要刷" placeholderTextColor={palette.faint} style={[styles.input, styles.multiline]} testID="goal-plan-input" value={plan} /></Field>
    {error ? <Text style={styles.error} testID="goal-form-error">{error}</Text> : null}
    <View style={styles.actions}>
      {onCancel ? <ActionButton label="取消" onPress={onCancel} testID="goal-form-cancel" /> : null}
      <ActionButton label={submitLabel} onPress={submit} testID="goal-form-submit" tone="primary" />
    </View>
  </View>;
}

function Field({ children, label, flex }: React.PropsWithChildren<{ label: string; flex?: boolean }>) {
  return <View style={[styles.field, flex && styles.flex]}><Text style={styles.label}>{label}</Text>{children}</View>;
}

const styles = StyleSheet.create({
  form: { gap: 14 },
  field: { gap: 7 },
  flex: { flex: 1 },
  row: { flexDirection: 'row', gap: 12 },
  label: { color: palette.ink, fontSize: 13, fontWeight: '700' },
  input: { backgroundColor: '#FBFAFE', borderColor: palette.border, borderRadius: 12, borderWidth: 1, color: palette.ink, fontSize: 15, minHeight: 46, paddingHorizontal: 13, paddingVertical: 10 },
  multiline: { minHeight: 74, textAlignVertical: 'top' },
  swatches: { flexDirection: 'row', flexWrap: 'wrap', gap: 10 },
  swatch: { borderRadius: 999, height: 34, width: 34 },
  swatchActive: { borderColor: palette.ink, borderWidth: 3 },
  error: { color: palette.danger, fontSize: 13, fontWeight: '600' },
  actions: { flexDirection: 'row', gap: 10, justifyContent: 'flex-end', marginTop: 4 },
});
